package org.marketreview.nativeapp;
import android.content.Context;
import android.media.MediaPlayer;
import android.system.Os;
import java.security.MessageDigest;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
final class ArchiveVideoReviewScreen extends LinearLayout implements AutoCloseable {
 interface Current {JSONObject current(String id);}
 private final JSONObject row;private final List<File>roots;private final Current current;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();private final TextView status;private final SurfaceView video;private final FrameLayout videoFrame;private final Button play,pause;private final List<Button>seekButtons=new ArrayList<>();private final List<JSONObject>segments=new ArrayList<>();private JSONArray allSegments=new JSONArray();private int segmentPage;private LinearLayout segmentView;private MediaPlayer player;private FileInputStream media;private boolean active,ready,disposed;private int generation;private int mediaWidth=16,mediaHeight=9;
 ArchiveVideoReviewScreen(Context context,JSONObject captured,List<File>allowedRoots,Current callback){super(context);try{row=new JSONObject(captured.toString());}catch(JSONException e){throw new IllegalArgumentException(e);}roots=new ArrayList<>();try{File privateRoot=context.getFilesDir().getCanonicalFile();for(File allowed:allowedRoots){File r=allowed.getCanonicalFile();if(r.getPath().startsWith(privateRoot.getPath()+File.separator))roots.add(r);}}catch(IOException ignored){}current=callback;setOrientation(VERTICAL);status=new TextView(context);status.setText("已归档视频与逐字稿复核（只读）；时间对应关系未自动核验");addView(status);videoFrame=new FrameLayout(context);videoFrame.setBackgroundColor(0xff000000);video=new SurfaceView(context);videoFrame.addView(video,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));addView(videoFrame,new LayoutParams(-1,240));video.getHolder().addCallback(new SurfaceHolder.Callback(){public void surfaceCreated(SurfaceHolder h){}public void surfaceChanged(SurfaceHolder h,int f,int w,int z){}public void surfaceDestroyed(SurfaceHolder h){release();}});LinearLayout controls=new LinearLayout(context);addView(controls);Button open=new Button(context);open.setText("核验并打开归档");controls.addView(open);play=new Button(context);play.setText("播放");controls.addView(play);pause=new Button(context);pause.setText("暂停");controls.addView(pause);play.setEnabled(false);pause.setEnabled(false);open.setOnClickListener(v->{if(!disposed){active=true;validate();}});play.setOnClickListener(v->{if(unchanged()&&ready&&player!=null)try{player.start();}catch(Exception e){failure("播放失败");}});pause.setOnClickListener(v->{if(player!=null&&ready)try{player.pause();}catch(Exception e){failure("暂停失败");}});ScrollView scroll=new ScrollView(context);LinearLayout text=new LinearLayout(context);text.setOrientation(VERTICAL);scroll.addView(text);addView(scroll,new LayoutParams(-1,0,1));JSONObject asr=row.optJSONObject("asrResult");if(asr==null)asr=new JSONObject();reader(text,"原始 ASR 全文",asr.optString("transcript",asr.optString("text")));reader(text,"采集原文",row.optString("originalText"));reader(text,"当前编辑文本（不继承时间轴）",row.optString("text"));allSegments=asr.optJSONArray("segments");if(allSegments==null)allSegments=new JSONArray();segmentView=new LinearLayout(context);segmentView.setOrientation(VERTICAL);text.addView(segmentView);LinearLayout pages=new LinearLayout(context);Button previous=new Button(context),next=new Button(context);previous.setText("上一页逐字稿");next.setText("下一页逐字稿");pages.addView(previous);pages.addView(next);text.addView(pages);previous.setOnClickListener(v->{if(segmentPage>0){segmentPage--;renderSegments();}});next.setOnClickListener(v->{if((segmentPage+1)*20<allSegments.length()){segmentPage++;renderSegments();}});renderSegments();}
 private void renderSegments(){segmentView.removeAllViews();seekButtons.clear();segments.clear();double duration=ready&&player!=null?player.getDuration()/1000.0:-1;for(int i=segmentPage*20;i<Math.min(allSegments.length(),(segmentPage+1)*20);i++){JSONObject segment=allSegments.optJSONObject(i);if(segment==null)continue;segments.add(segment);Button seek=new Button(getContext());seek.setText("试定位 "+segment.opt("start")+"–"+segment.opt("end")+" 秒（对应关系未核验）");seek.setEnabled(ready&&ArchiveVideoReviewModel.seekSeconds(segment,duration)>=0);seekButtons.add(seek);segmentView.addView(seek);reader(segmentView,"",segment.optString("text"));seek.setOnClickListener(v->{if(!unchanged()||!ready||player==null)return;try{double seconds=ArchiveVideoReviewModel.seekSeconds(segment,player.getDuration()/1000.0);if(seconds>=0){status.setText("正在试定位；对应关系未核验");player.seekTo((long)(seconds*1000),MediaPlayer.SEEK_CLOSEST);}}catch(Exception e){failure("试定位失败");}});}}
 private void reader(LinearLayout target,String label,String value){TextView text=new TextView(getContext());text.setText(label+"\n"+value);text.setTextIsSelectable(true);target.addView(text);}
 private boolean unchanged(){try{if(active&&!disposed&&current!=null&&ArchiveVideoReviewModel.canonical(row).equals(ArchiveVideoReviewModel.canonical(current.current(row.optString("id")))))return true;}catch(Exception ignored){}failure("作品记录版本已改变，请重新打开");return false;}
 private void release(){generation++;ready=false;play.setEnabled(false);pause.setEnabled(false);for(Button b:seekButtons)b.setEnabled(false);if(player!=null){player.setOnPreparedListener(null);player.setOnVideoSizeChangedListener(null);player.setOnSeekCompleteListener(null);player.setOnErrorListener(null);player.release();player=null;}if(media!=null){try{media.close();}catch(IOException ignored){}media=null;}}
 private void failure(String reason){release();status.setText(reason);}
 private static void closeInput(FileInputStream input){if(input!=null)try{input.close();}catch(IOException ignored){}}
 private FileInputStream openVerified(JSONObject result) throws Exception {
  String path=result.getString("path");ParcelFileDescriptor descriptor=ParcelFileDescriptor.open(new File(path),ParcelFileDescriptor.MODE_READ_ONLY);
  FileInputStream input=null;
  try {String actual=Os.readlink("/proc/self/fd/"+descriptor.getFd());File file=new File(actual).getCanonicalFile();boolean inside=false;for(File root:roots)if(file.getPath().startsWith(root.getCanonicalPath()+File.separator))inside=true;if(!inside||!file.getPath().equals(new File(path).getCanonicalPath()))throw new IOException("descriptor path changed");input=new ParcelFileDescriptor.AutoCloseInputStream(descriptor);JSONObject archive=row.getJSONObject("archive");MessageDigest hash=MessageDigest.getInstance("SHA-256");byte[]buffer=new byte[65536];long total=0;int count;while((count=input.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();hash.update(buffer,0,count);total+=count;if(total>256L*1024*1024)throw new IOException("too large");}StringBuilder digest=new StringBuilder();for(byte x:hash.digest())digest.append(String.format(Locale.ROOT,"%02x",x&255));if(total!=archive.getLong("bytes")||!digest.toString().equalsIgnoreCase(archive.getString("sha256")))throw new IOException("descriptor digest changed");input.getChannel().position(0);return input;
  }catch(Exception e){if(input!=null)closeInput(input);else descriptor.close();throw e;}
 }
 private void validate(){release();if(!unchanged())return;final int token=generation;final JSONObject now;try{now=new JSONObject(current.current(row.optString("id")).toString());}catch(Exception e){failure("当前作品版本不可读");return;}status.setText("正在只读核验归档 SHA256…");worker.execute(()->{JSONObject result=ArchiveVideoReviewModel.inspect(row,now,roots);FileInputStream prepared=null;String error="";if(result.optBoolean("playable"))try{prepared=openVerified(result);}catch(Exception e){error="本机归档描述符核验失败："+e.getClass().getSimpleName();}final FileInputStream verified=prepared;final String failure=error;main.post(()->{if(disposed||!active||token!=generation){closeInput(verified);return;}status.setText(result.optString("reason"));if(!failure.isEmpty()){closeInput(verified);failure(failure);return;}if(!result.optBoolean("playable")||!unchanged()){closeInput(verified);return;}if(!video.getHolder().getSurface().isValid()){closeInput(verified);failure("视频显示窗口尚未就绪，请重新打开");return;}try{media=verified;
player=new MediaPlayer();player.setOnVideoSizeChangedListener((p,w,h)->{if(p==player&&w>0&&h>0){mediaWidth=w;mediaHeight=h;requestLayout();}});player.setDataSource(media.getFD(),0,row.getJSONObject("archive").getLong("bytes"));player.setDisplay(video.getHolder());player.setOnSeekCompleteListener(p->{if(p==player&&token==generation&&active)status.setText("已试定位 "+String.format(Locale.ROOT,"%.2f",p.getCurrentPosition()/1000.0)+" 秒；时间对应关系未核验");});player.setOnErrorListener((p,what,extra)->{if(p==player)failure("归档格式或系统解码器不支持此视频");return true;});player.setOnPreparedListener(p->{if(p!=player||token!=generation||!unchanged())return;ready=true;play.setEnabled(true);pause.setEnabled(true);double duration=p.getDuration()/1000.0;for(int i=0;i<seekButtons.size();i++){boolean valid=ArchiveVideoReviewModel.seekSeconds(segments.get(i),duration)>=0;seekButtons.get(i).setEnabled(valid);if(!valid)seekButtons.get(i).setText("时间无效或超出实际时长；原文保留");}status.setText("已就绪，等待手动播放；时间对应关系未自动核验");});player.prepareAsync();}catch(Exception e){failure("本机归档播放器打开失败："+e.getClass().getSimpleName());}});});}
 protected void onMeasure(int widthSpec,int heightSpec){int w=MeasureSpec.getSize(widthSpec),h=MeasureSpec.getSize(heightSpec);if(w>0&&h>0){int displayHeight=Math.min(w*mediaHeight/mediaWidth,Math.max(100,h/3));LayoutParams frame=(LayoutParams)videoFrame.getLayoutParams();frame.height=displayHeight;int displayWidth=Math.min(w,displayHeight*mediaWidth/mediaHeight);FrameLayout.LayoutParams surface=(FrameLayout.LayoutParams)video.getLayoutParams();surface.width=displayWidth;surface.height=displayWidth*mediaHeight/mediaWidth;}super.onMeasure(widthSpec,heightSpec);}
 void setActive(boolean value){active=value;if(!value)release();}
 public void close(){active=false;disposed=true;release();worker.shutdownNow(); // Queued completions retain ownership and must run to close their descriptor.
 }
 boolean back(){setActive(false);return false;}
 JSONObject saveState(){JSONObject out=new JSONObject();try{out.put("id",row.optString("id")).put("segmentPage",segmentPage).put("paused",true);}catch(JSONException ignored){}return out;}
 void restoreState(JSONObject state){setActive(false);if(state!=null&&row.optString("id").equals(state.optString("id"))){segmentPage=Math.max(0,Math.min(state.optInt("segmentPage"),Math.max(0,(allSegments.length()-1)/20)));renderSegments();}}
 protected void onDetachedFromWindow(){setActive(false);super.onDetachedFromWindow();}
}





